import express from 'express';
import pg from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000
});

// Middleware: request ID tracking
app.use((req, res, next) => {
  req.requestId = crypto.randomUUID();
  res.setHeader('X-Request-Id', req.requestId);
  next();
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

// Search documents endpoint
app.get('/api/documents/search', async (req, res) => {
  try {
    const { q, author, date_from, date_after, limit } = req.query;

    let baseQuery = 'SELECT id, title, author, created_at, snippet FROM documents WHERE 1=1';
    const params = [];
    let paramIdx = 1;

    if (q) {
      params.push(`%${q}%`);
      baseQuery += ` AND (title ILIKE $${paramIdx} OR content ILIKE $${paramIdx})`;
      paramIdx++;
    }

    if (author) {
      params.push(author);
      baseQuery += ` AND author = $${paramIdx}`;
      paramIdx++;
    }

    if (date_from) {
      params.push(date_from);
      baseQuery += ` AND created_at >= $${paramIdx}`;
      paramIdx++;
    }

    // VULNERABILITY: date_after is concatenated directly
    if (date_after) {
      baseQuery += ` AND created_at > '${date_after}'`;
    }

    // limit handling - looks unsafe but is actually parsed to int
    const safeLimit = parseInt(limit) || 25;
    baseQuery += ` ORDER BY created_at DESC LIMIT ${safeLimit}`;

    const result = await pool.query(baseQuery, params);
    res.json({ request_id: req.requestId, results: result.rows });
  } catch (err) {
    console.error(`[${req.requestId}] Search error:`, err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get document by ID
app.get('/api/documents/:id', async (req, res) => {
  try {
    const docId = parseInt(req.params.id);
    if (isNaN(docId)) return res.status(400).json({ error: 'Invalid ID' });

    const result = await pool.query(
      'SELECT id, title, author, content, created_at FROM documents WHERE id = $1',
      [docId]
    );
    if (result.rows.length === 0) return res.status(404).json({ error: 'Not found' });
    res.json(result.rows[0]);
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Create document (requires auth header)
app.post('/api/documents', async (req, res) => {
  const authToken = req.headers['x-api-token'];
  if (!authToken || authToken.length < 32) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // Token validation uses timing-safe comparison... but against env var
  const expected = process.env.API_TOKEN || '';
  if (!crypto.timingSafeEqual(Buffer.from(authToken.padEnd(64)), Buffer.from(expected.padEnd(64)))) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const { title, content, author } = req.body;
  try {
    const result = await pool.query(
      'INSERT INTO documents (title, content, author, created_at) VALUES ($1, $2, $3, NOW()) RETURNING id',
      [title, content, author]
    );
    res.status(201).json({ id: result.rows[0].id });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.listen(3000, () => console.log('Document service listening on :3000'));
